using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("Unity: " + Application.unityVersion);
            foreach (var p in UnityEditor.PackageManager.PackageInfo.GetAllRegisteredPackages())
                if (p.name.Contains("xr") || p.name.Contains("render-pipelines") || p.name.Contains("inputsystem"))
                    result.Log(p.name + " " + p.version);
            foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
            {
                result.Log("ROOT " + root.name + " id=" + root.GetInstanceID());
                foreach (var t in root.GetComponentsInChildren<Transform>(true))
                {
                    var cs = t.GetComponents<Component>();
                    result.Log("  " + t.name + " id=" + t.gameObject.GetInstanceID() + " components=" + string.Join(",", System.Array.ConvertAll(cs, c => c == null ? "MISSING" : c.GetType().FullName)));
                }
            }

            foreach (var guid in AssetDatabase.FindAssets("t:Prefab", new[]{"Assets"}))
                result.Log("PREFAB " + AssetDatabase.GUIDToAssetPath(guid));
            foreach (var guid in AssetDatabase.FindAssets("t:Model", new[]{"Assets"}))
                result.Log("MODEL " + AssetDatabase.GUIDToAssetPath(guid));
        }
    }
}

