using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            int emissive = 0;
            foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
            {
                foreach (var l in root.GetComponentsInChildren<Light>(true))
                    result.Log("Light " + l.name + " type=" + l.type + " intensity=" + l.intensity + " color=" + l.color + " mode=" + l.lightmapBakeType + " shadows=" + l.shadows + " pos=" + l.transform.position + " rot=" + l.transform.eulerAngles);
                foreach (var r in root.GetComponentsInChildren<Renderer>(true))
                    foreach (var m in r.sharedMaterials)
                        if (m != null && m.IsKeywordEnabled("_EMISSION"))
                            emissive++;
            }

            result.Log("Ambient " + RenderSettings.ambientMode + " intensity=" + RenderSettings.ambientIntensity + " skybox=" + RenderSettings.skybox + " reflection=" + RenderSettings.reflectionIntensity + " emissive renderers=" + emissive + " bakedGI=" + (Lightmapping.lightingSettings != null && Lightmapping.lightingSettings.bakedGI));
            var so = new SerializedObject(UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline);
            foreach (var n in new[]{"m_ReflectionProbeBoxProjection", "m_ReflectionProbeBlending", "m_AdditionalLightsRenderingMode", "m_SupportsHDR"})
            {
                var p = so.FindProperty(n);
                if (p != null)
                    result.Log(n + "=" + p.propertyType + " " + (p.propertyType == SerializedPropertyType.Boolean ? p.boolValue.ToString() : p.intValue.ToString()));
            }

            foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
                foreach (var area in root.GetComponentsInChildren<UnityEngine.XR.Interaction.Toolkit.Locomotion.Teleportation.TeleportationArea>(true))
                    result.Log("Teleport mask=" + area.interactionLayers.value + " layer=" + area.gameObject.layer + " provider=" + area.teleportationProvider);
        }
    }
}

